  function codexRpc(method,params={},timeoutMs=30000){return new Promise((resolve,reject)=>{if(!codexSocket||codexSocket.readyState!==WebSocket.OPEN)return reject(Error('Codex غير متصل'));let id=++codexRpcId,t=setTimeout(()=>{codexPending.delete(id);reject(Error('انتهت مهلة رد Codex: '+method))},timeoutMs);codexPending.set(id,{resolve,reject,t});codexSocket.send(JSON.stringify({method,id,params}))})}
