  async function codexConnect(isReconnect=false){codexSetError('');try{clearTimeout(codexReconnectTimer);codexReconnectTimer=null;codexClosing=true;if(codexSocket)try{codexSocket.close()}catch{};codexClosing=false;codexReady=false;codexSetStatus(isReconnect?'إعادة الاتصال…':'جارٍ الاتصال…','warn');await fetch('/api/session',{method:'POST',credentials:'same-origin',cache:'no-store'});let scheme=location.protocol==='https:'?'wss:':'ws:',url=scheme+'//'+location.host+'/api/ws',ws=new WebSocket(url);codexSocket=ws;ws.onmessage=e=>{try{codexHandle(JSON.parse(e.data))}catch{}};ws.onclose=()=>{if(codexSocket!==ws)return;codexReady=false;codexSetStatus('غير متصل');for(let [id,p] of codexPending){clearTimeout(p.t);p.reject(Error('انقطع اتصال Codex'));codexPending.delete(id)}for(let [id,w] of codexTurnWaiters){w.reject(Error('انقطع اتصال Codex'));codexTurnWaiters.delete(id)}scheduleCodexReconnect()};ws.onerror=()=>codexSetError('تعذر الاتصال بخدمة Codex على Vercel.');await new Promise((res,rej)=>{let t=setTimeout(()=>rej(Error('تعذر فتح WebSocket إلى /api/ws')),12000);ws.onopen=()=>{clearTimeout(t);res()};ws.addEventListener('close',()=>{clearTimeout(t);rej(Error('أُغلق اتصال Codex'))},{once:true})});await codexRpc('initialize',{clientInfo:{name:'aiway-vercel',title:'AiWay',version:'2.0.0'},capabilities:{experimentalApi:true}},30000);codexNotify('initialized',{});codexReady=true;codexReconnectAttempts=0;codexConnectionId++;codexSetStatus('متصل','ok');await codexLoadAccount(false);if(chat?.files)codexPushWorkspace().catch(()=>{})}catch(e){codexReady=false;codexSetStatus('غير متصل');codexSetError(e.message);scheduleCodexReconnect()}}
