  function toolActivityHTML(m){let active=m.toolActivity||pendingTool(m.text);if(!m.loading||!active)return'';let meta=toolMeta(active.name);return `<div class="tool-activity"><span class="tool-activity-icon"><i class="tool-spin" data-lucide="${meta.icon}" width="15"></i></span><span class="tool-activity-text"><strong>${esc(meta.label)}...</strong>${active.path?`<span>${esc(active.path)}</span>`:''}</span></div>`}
  async function copyText(text){text=String(text??'');try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);return true}}catch{}let ta=document.createElement('textarea');ta.value=text;ta.style.cssText='position:fixed;opacity:0;pointer-events:none';document.body.appendChild(ta);ta.focus();ta.select();let ok=false;try{ok=document.execCommand('copy')}catch{}ta.remove();return ok}
  function renderMessage(m){let isUser=m.role==='user',bodyText=isUser?m.text:visibleAssistantText(m.text);return `<article class="message ${isUser?'user':'assistant'}" data-message="${esc(m.id)}"><div class="msg-icon"><i data-lucide="${isUser?'user-round':'sparkles'}" width="16"></i></div><div class="msg-main"><div class="msg-head">${isUser?'أنت':'AiWay'} ${!isUser&&m.providerName?`<span style="font-size:9px;color:#8794a7;font-weight:500">${esc(m.providerName)}</span>`:''} <time>${new Date(m.time).toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'})}</time></div>${m.reason?`<details class="reason-box" ${m.loading?'open':''}><summary><i data-lucide="sparkles" width="14"></i> ${m.loading?'يفكر الآن...':'تفكير النموذج'}</summary><div class="reason-content">${esc(m.reason)}</div></details>`:''}<div class="msg-body">${isUser?esc(bodyText||'').replace(/\n/g,'<br>'):markdown(bodyText)}${m.loading&&!bodyText&&!pendingTool(m.text)?'<div class="typing"><span></span><span></span><span></span></div>':''}${m.error?`<div style="color:#d45c62">${esc(m.error)}</div>`:''}</div>${toolActivityHTML(m)}${m.files?.length?`<div class="file-tags">${m.files.map(f=>`<span class="file-tag">${esc(f.name)}</span>`).join('')}</div>`:''}${m.toolEvents?.length?`<div class="tool-events">${m.toolEvents.map(x=>`<span class="tool-event">${esc(x)}</span>`).join('')}</div>`:''}${!m.loading&&(m.text||isUser)?`<div class="msg-actions"><button data-copy-message="${esc(m.id)}"><i data-lucide="copy" width="13"></i> ${isUser?'نسخ رسالتي':'نسخ الرد'}</button></div>`:''}</div></article>`}
  function patchMessage(m){const el=$('messages').querySelector(`[data-message="${m.id}"]`);if(!el){renderChat();return}const body=el.querySelector('.msg-body'),shown=visibleAssistantText(m.text);if(body)body.innerHTML=markdown(shown)+(m.loading&&!shown&&!pendingTool(m.text)?'<div class="typing"><span></span><span></span><span></span></div>':'')+(m.error?`<div style="color:#d45c62">${esc(m.error)}</div>`:'');let reasonBox=el.querySelector('.reason-box');if(m.reason){if(!reasonBox){el.querySelector('.msg-head')?.insertAdjacentHTML('afterend','<details class="reason-box"><summary><i data-lucide="sparkles" width="14"></i> <span class="reason-label">تفكير النموذج</span></summary><div class="reason-content"></div></details>');reasonBox=el.querySelector('.reason-box')}if(reasonBox){reasonBox.querySelector('.reason-content').textContent=m.reason;let label=reasonBox.querySelector('.reason-label');if(label)label.textContent=m.loading?'يفكر الآن...':'تفكير النموذج'}}let oldActivity=el.querySelector('.tool-activity'),activity=toolActivityHTML(m);if(activity){if(oldActivity)oldActivity.outerHTML=activity;else body?.insertAdjacentHTML('afterend',activity)}else oldActivity?.remove();icons();scrollEnd()}
  function refreshLastMessage(immediate=false){const m=chat?.messages?.at(-1);if(!m)return;pendingStreamMessage=m;if(immediate){if(streamRaf)cancelAnimationFrame(streamRaf);streamRaf=0;let el=$('messages').querySelector(`[data-message="${m.id}"]`);if(el){el.outerHTML=renderMessage(m);icons();scrollEnd()}else renderChat();return}if(streamRaf)return;streamRaf=requestAnimationFrame(()=>{streamRaf=0;let msg=pendingStreamMessage;pendingStreamMessage=null;if(msg&&chat?.messages?.includes(msg))patchMessage(msg)})}
  function renderAttachments(){$('attachments').innerHTML=attached.map((f,i)=>`<div class="attach-chip"><i data-lucide="${f.mime.startsWith('image/')?'image':'file-text'}" width="13"></i><span>${esc(f.name)}</span><button data-remove-attachment="${i}" title="إزالة">×</button></div>`).join('');icons()}
  function setBusy(value){busy=value;$('scrollArea').classList.toggle('streaming',value);$('sendBtn').classList.toggle('stop',value);$('sendBtn').title=value?'إيقاف التوليد':'إرسال';$('sendBtn').innerHTML=value?'<i data-lucide="square" width="14" fill="currentColor"></i>':'<i data-lucide="arrow-up" width="18" stroke-width="2.5"></i>';icons()}
  function stopGeneration(){controller?.abort();if(codexActiveTurnId&&chat?.codexThreadId)codexRpc('turn/interrupt',{threadId:chat.codexThreadId,turnId:codexActiveTurnId},5000).catch(()=>{})}
  function modelLabel(){let p=provider();$('modelLabel').textContent=p.model?((p.model.length>23?p.model.slice(0,20)+'...':p.model)):(p.type==='codex'?'Codex الافتراضي':'اختر نموذجاً');$('thinkingLabel').textContent=({off:'بدون تفكير',low:'تفكير خفيف',medium:'تفكير متوازن',high:'تفكير عميق'})[effort]||'تفكير متوازن';$('thinkingBtn').classList.toggle('thinking-active',effort!=='off');document.querySelectorAll('#thinkingPopover [data-effort]').forEach(b=>{let selected=b.dataset.effort===effort;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
  function renderModels(){let p=provider(),term=$('modelSearch').value.trim().toLowerCase(),models=[...new Set([p.model,...(p.models||[])].filter(Boolean))].filter(m=>m.toLowerCase().includes(term));$('modelPopoverTitle').textContent='النماذج - '+p.name;$('modelList').innerHTML=models.length?models.slice(0,150).map(m=>`<button class="${m===p.model?'selected':''}" data-model="${esc(m)}"><i data-lucide="${m===p.model?'check':'bot'}" width="14"></i><span dir="ltr" style="overflow:hidden;text-overflow:ellipsis">${esc(m)}</span></button>`).join(''):'<div class="empty-mini">لا توجد نماذج. أضف مفتاحاً واجلب النماذج من الإعدادات.</div>';icons()}
  function closePopovers(){$('modelPopover').classList.add('hidden');$('thinkingPopover').classList.add('hidden')}
  async function readAttachment(file){if(file.size>4*1024*1024)throw Error('الحد الأقصى لكل مرفق 4 ميجابايت');return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve({name:file.name,mime:file.type||'text/plain',data:reader.result,size:file.size});reader.onerror=()=>reject(Error('تعذر قراءة الملف'));reader.readAsDataURL(file)})}
  function dataToText(f){try{let b64=f.data.split(',')[1];return new TextDecoder().decode(Uint8Array.from(atob(b64),c=>c.charCodeAt(0)))}catch{return ''}}
  function isText(f){return !f.mime.startsWith('image/')&&f.mime!=='application/pdf'}
  function fileContext(f){return `\n\n[ملف مرفق: ${f.name}]\n${dataToText(f).slice(0,80000)}\n[/نهاية الملف]`}
  function projectContext(){let parts=[];let useProject=!$('ctxProject')||$('ctxProject').checked;if(useProject){let entries=Object.entries(chat.files||{}).slice(0,30);if($('ctxCurrent')?.checked&&selectedFile&&chat.files[selectedFile]!=null)entries=[[selectedFile,chat.files[selectedFile]],...entries.filter(([n])=>n!==selectedFile)];if(entries.length)parts.push('ملفات مساحة العمل الحالية (قد تكون مقتطعة):'+entries.map(([name,code])=>`\n--- ${name} ---\n${code.slice(0,12000)}`).join(''))}if($('ctxErrors')?.checked&&previewErrors.length)parts.push('آخر أخطاء المعاينة:\n'+previewErrors.slice(-5).join('\n'));if($('ctxTerminal')?.checked&&terminalHistory.length)parts.push('آخر مخرجات Terminal:\n'+terminalHistory.slice(-12).join('\n'));return parts.length?'\n\n'+parts.join('\n\n'):''}
  function effectiveSystem(){return systemPrompt+(agentMode?'\n\nوضع Agent مفعّل: افحص المشروع أولاً، خطط باختصار، نفّذ التعديلات المطلوبة فعلياً، تحقق من الاتساق والأخطاء، ولا تتوقف عند الشرح إذا كانت المهمة تتطلب تعديل الملفات.':'')}
  function commonMessages(history){return [{role:'system',content:effectiveSystem()+TOOL_GUIDE+projectContext()},...history.map(m=>{let text=m.text||'';if(m.role==='user'){let extras=(m.attachments||[]).filter(isText);text+=extras.map(fileContext).join('');let images=(m.attachments||[]).filter(f=>f.mime.startsWith('image/'));if(images.length)return{role:'user',content:[{type:'text',text:text||'حلل المرفقات'},...images.map(f=>({type:'image_url',image_url:{url:f.data}}))]}}return{role:m.role,content:text}})]}
  async function consumeSSE(response,onData){if(!response.ok){let text=await response.text();try{text=JSON.parse(text).error?.message||text}catch{}throw Error(`${response.status}: ${text.slice(0,300)}`)}if(!response.body)throw Error('المتصفح لا يدعم تدفق الاستجابة');let reader=response.body.getReader(),decoder=new TextDecoder(),buffer='';function parse(data){try{return JSON.parse(data)}catch{return null}}while(true){let {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let blocks=buffer.split(/\r?\n\r?\n/);buffer=blocks.pop();for(let block of blocks){let data=block.split(/\r?\n/).filter(l=>l.startsWith('data:')).map(l=>l.slice(5).trimStart()).join('\n');if(data&&data!=='[DONE]'){let event=parse(data);if(event)onData(event)}}}if(buffer.trim()){let data=buffer.split(/\r?\n/).find(l=>l.startsWith('data:'));if(data){let event=parse(data.slice(5).trimStart());if(event)onData(event)}}}
  async function runCompatible(p,history,output){let key=keyFor(p);if(!key&&p.type!=='compatible')throw Error('أضف مفتاح API من الإعدادات أولاً');let headers={'Content-Type':'application/json'};if(key)headers.Authorization='Bearer '+key;if(p.type==='openrouter'){headers['HTTP-Referer']=location.origin==='null'?'https://localhost':location.origin;headers['X-OpenRouter-Title']='AiWay'}let body={model:p.model,messages:commonMessages(history),stream:true};if(p.type==='openrouter'&&effort!=='off')body.reasoning={effort};else if(p.type==='compatible'&&effort!=='off')body.reasoning_effort=effort;let res=await fetch(p.url.replace(/\/+$/,'')+'/chat/completions',{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});await consumeSSE(res,data=>{if(data.error)throw Error(data.error.message||'خطأ من المزود');let d=data.choices?.[0]?.delta;if(!d)return;let reason=d.reasoning||d.reasoning_content||d.reasoning_details?.map(x=>x.text||'').join('')||'';if(reason)output.reason+=reason;if(typeof d.content==='string'){output.text+=d.content;processToolCalls(output)}if(chat.messages.at(-1)===output)refreshLastMessage()})}
  async function runGemini(p,history,output){let key=keyFor(p);if(!key)throw Error('أضف مفتاح Gemini API من الإعدادات أولاً');let contents=history.map(m=>{let parts=[{text:(m.text||'')+(m.role==='user'?(m.attachments||[]).filter(isText).map(fileContext).join(''):'')}];if(m.role==='user')for(let f of m.attachments||[])if(f.mime.startsWith('image/')||f.mime==='application/pdf')parts.push({inlineData:{mimeType:f.mime,data:f.data.split(',')[1]}});return{role:m.role==='assistant'?'model':'user',parts}});let body={systemInstruction:{parts:[{text:effectiveSystem()+TOOL_GUIDE+projectContext()}]},contents,generationConfig:{}};if(effort!=='off'){body.generationConfig.thinkingConfig={includeThoughts:true};if(p.model.includes('2.5'))body.generationConfig.thinkingConfig.thinkingBudget=({low:512,medium:2048,high:8192})[effort];else body.generationConfig.thinkingConfig.thinkingLevel=effort.toUpperCase()}else if(p.model.includes('2.5-flash'))body.generationConfig.thinkingConfig={thinkingBudget:0};let model=p.model.replace(/^models\//,''),url=p.url.replace(/\/+$/,'')+'/models/'+encodeURIComponent(model)+':streamGenerateContent?alt=sse',headers={'Content-Type':'application/json','x-goog-api-key':key};let res=await fetch(url,{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});await consumeSSE(res,data=>{if(data.error)throw Error(data.error.message||'خطأ من Gemini');for(let part of data.candidates?.[0]?.content?.parts||[]){if(part.text){if(part.thought)output.reason+=part.text;else{output.text+=part.text;processToolCalls(output)}}}if(chat.messages.at(-1)===output)refreshLastMessage()})}
  async function runOpenCode(p,history,output){let current=chat,base=p.url.replace(/\/+$/,'');let key=keyFor(p),headers={'Content-Type':'application/json'};if(key)headers.Authorization='Basic '+btoa('opencode:'+key);current.opencodeSessions ||= {};let sessionId=current.opencodeSessions[p.id];if(!sessionId){let create=await fetch(base+'/session',{method:'POST',headers,body:JSON.stringify({title:current.title}),signal:controller.signal});if(!create.ok)throw Error('تعذر إنشاء جلسة OpenCode: '+create.status);sessionId=(await create.json()).id;current.opencodeSessions[p.id]=sessionId}let last=history.at(-1);let parts=[{type:'text',text:last.text+(last.attachments||[]).filter(isText).map(fileContext).join('')}];for(let f of last.attachments||[])if(f.mime.startsWith('image/'))parts.push({type:'file',mime:f.mime,url:f.data,filename:f.name});let body={parts,system:effectiveSystem()+TOOL_GUIDE+projectContext()};if(p.model?.includes('/')){let [providerID,...rest]=p.model.split('/');body.model={providerID,modelID:rest.join('/')}}let res=await fetch(base+'/session/'+encodeURIComponent(sessionId)+'/message',{method:'POST',headers,body:JSON.stringify(body),signal:controller.signal});if(!res.ok)throw Error('OpenCode: '+res.status+' '+(await res.text()).slice(0,200));let data=await res.json();output.text=(data.parts||[]).filter(x=>x.type==='text').map(x=>x.text).join('\n');output.reason=(data.parts||[]).filter(x=>x.type==='reasoning').map(x=>x.text).join('\n');processToolCalls(output);if(chat.messages.at(-1)===output)refreshLastMessage()}
  async function send(){if(busy){stopGeneration();return}let text=$('prompt').value.trim();if(!text&&!attached.length)return;let p=chooseProviderFor(text);if(p.type!=='codex'&&!p?.model){toast('اختر نموذجاً من الإعدادات أولاً');openSettings();return}if(!['opencode','compatible','codex'].includes(p.type)&&!keyFor(p)){toast(p.type==='gemini'?'أضف مفتاح Gemini API':'أضف مفتاح API للمتابعة');openSettings();return}if(!['gemini'].includes(p.type)&&attached.some(f=>f.mime==='application/pdf')){toast('ملفات PDF المباشرة مدعومة مع Gemini فقط حالياً.');return}let files=attached.splice(0);let user={id:uid(),role:'user',text,attachments:files,files:files.map(f=>({name:f.name})),time:Date.now()};chat.messages.push(user);if(chat.messages.length===1)chat.title=(text||files[0]?.name||'مشروع جديد').slice(0,36);$('prompt').value='';$('prompt').style.height='auto';renderAttachments();let answer={id:uid(),role:'assistant',text:'',reason:'',time:Date.now(),loading:true,providerName:p.name};chat.messages.push(answer);renderChat();setBusy(true);controller=new AbortController();const currentChat=chat;try{if(p.type==='codex')await runCodex(p,chat.messages.slice(0,-1),answer);else if(p.type==='gemini')await runGemini(p,chat.messages.slice(0,-1),answer);else if(p.type==='opencode')await runOpenCode(p,chat.messages.slice(0,-1),answer);else await runCompatible(p,chat.messages.slice(0,-1),answer);if(!answer.text&&!answer.reason)answer.error='لم يرجع النموذج محتوى. جرّب نموذجاً آخر.'}catch(e){if(e.name!=='AbortError')answer.error=(e instanceof TypeError?'تعذر الاتصال. تحقق من الاتصال وإعدادات المزود.':e.message)}finally{if(currentChat===chat)processToolCalls(answer);answer.loading=false;if(currentChat===chat){refreshLastMessage(true);saveChat()}else if(db){let req=store('readwrite').put(structuredClone(currentChat));req.onerror=()=>toast('تعذر حفظ المحادثة')}if(db)chats=await allChats();setBusy(false);controller=null}}
  function openSettings(){$('settingsModal').classList.remove('hidden');fillProviderSelect();fillProvider(activeId);$('sidebar').classList.remove('mobile-open');closePopovers()}
  function closeSettings(){$('settingsModal').classList.add('hidden')}
  function fillProviderSelect(){let selected=$('providerSelect').value||activeId;$('providerSelect').innerHTML=providers.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('providerSelect').value=providers.some(p=>p.id===selected)?selected:activeId}
  function fillProvider(id){let p=providers.find(x=>x.id===id);if(!p)return;let isCodex=p.type==='codex';$('providerSelect').value=id;$('providerName').value=p.name;$('providerType').value=p.type;$('providerUrl').value=p.url;$('providerUrl').disabled=isCodex;$('providerModel').value=p.model;$('providerKey').value=isCodex?'':keyFor(p);$('providerKey').disabled=isCodex;$('rememberKey').checked=!isCodex&&!!p.remember;$('rememberKey').disabled=isCodex;$('systemPrompt').value=systemPrompt;$('modelCount').textContent=p.models?.length?`${p.models.length} نموذج متاح`:'';$('modelOptions').innerHTML=(p.models||[]).map(m=>`<option value="${esc(m)}"></option>`).join('')}
  function settingsDraft(){return{id:$('providerSelect').value,name:$('providerName').value.trim()||'مزود جديد',type:$('providerType').value,url:$('providerUrl').value.trim().replace(/\/+$/,''),model:$('providerModel').value.trim(),key:$('providerKey').value.trim(),remember:$('rememberKey').checked}}
  function saveSettings(){let draft=settingsDraft();if(draft.type!=='codex'&&!/^https?:\/\//i.test(draft.url)){toast('اكتب رابط URL صحيح يبدأ بـ http أو https');return}let p=providers.find(x=>x.id===draft.id);Object.assign(p,{name:draft.name,type:draft.type,url:draft.url,model:draft.model,remember:draft.remember});localStorage.removeItem('aiway.key.'+p.id);sessionStorage.removeItem('aiway.key.'+p.id);if(draft.key)(draft.remember?localStorage:sessionStorage).setItem('aiway.key.'+p.id,draft.key);activeId=p.id;systemPrompt=$('systemPrompt').value.trim()||DEFAULT_SYSTEM;persistConfig();modelLabel();closeSettings();toast('تم حفظ الإعدادات')}
  async function fetchModels(){let d=settingsDraft(),btn=$('fetchModels');if(d.type!=='codex'&&!/^https?:\/\//i.test(d.url)){toast('أدخل رابط المزود أولاً');return}btn.disabled=true;btn.textContent='جارٍ جلب النماذج...';try{let models=[];if(d.type==='codex'){if(!codexReady)await codexConnect();if(codexAccountData?.type!=='chatgpt')throw Error('سجّل الدخول بحساب ChatGPT أولاً');models=await codexSyncModels()}else{let url,headers={};if(d.type==='gemini'){if(!d.key)throw Error('أضف Gemini API Key');url=d.url+'/models';headers['x-goog-api-key']=d.key}else if(d.type==='opencode'){url=d.url+'/config/providers';if(d.key)headers.Authorization='Basic '+btoa('opencode:'+d.key)}else{url=d.url+'/models';if(d.key)headers.Authorization='Bearer '+d.key}let res=await fetch(url,{headers});if(!res.ok)throw Error('HTTP '+res.status+': '+(await res.text()).slice(0,130));let data=await res.json();if(d.type==='gemini')models=(data.models||[]).filter(x=>!x.supportedGenerationMethods||x.supportedGenerationMethods.includes('generateContent')).map(x=>x.name.replace(/^models\//,''));else if(d.type==='opencode')models=(data.providers||[]).flatMap(x=>Object.keys(x.models||{}).map(m=>x.id+'/'+m));else models=(data.data||data.models||[]).map(x=>typeof x==='string'?x:x.id).filter(Boolean);models=[...new Set(models)].sort()}if(!models.length)throw Error('لم يتم العثور على نماذج');let p=providers.find(x=>x.id===d.id);p.models=models;$('modelOptions').innerHTML=models.map(m=>`<option value="${esc(m)}"></option>`).join('');$('modelCount').textContent=models.length+' نموذج متاح';if(!d.model)$('providerModel').value=models[0];persistConfig();renderModels();toast(`تم جلب ${models.length} نموذج.`)}catch(e){toast('تعذر جلب النماذج: '+e.message)}finally{btn.disabled=false;btn.innerHTML='<i data-lucide="refresh-cw" width="14" style="display:inline;vertical-align:middle"></i> جلب النماذج من المزود';icons()}}
  function toggleWorkspace(show){$('workspace').classList.toggle('hidden',!show);$('workspaceToggle').classList.toggle('on',show);$('sidebar').classList.remove('mobile-open');if(show)renderFiles()}
  function renderFiles(){if(!chat)return;let names=Object.keys(chat.files||{}),term=($('fileSearch')?.value||'').toLowerCase();if(selectedFile&&!names.includes(selectedFile))selectedFile=null;if(!selectedFile&&names.length)selectedFile=names[0];if(selectedFile&&!openFiles.includes(selectedFile))openFiles.push(selectedFile);openFiles=openFiles.filter(n=>names.includes(n)).slice(-8);let shown=term?names.filter(n=>n.toLowerCase().includes(term)):names;$('fileList').innerHTML=shown.length?shown.map(name=>`<button class="file-row ${name===selectedFile?'active':''}" data-file="${esc(name)}"><i data-lucide="${name.endsWith('.html')?'file-code-2':name.endsWith('.css')?'palette':'file-code'}" width="14"></i><span>${esc(name)}</span><span class="remove-file" data-remove-file="${esc(name)}"><i data-lucide="x" width="13"></i></span></button>`).join(''):'<div class="empty-mini">لا توجد ملفات مطابقة.</div>';$('openFileTabs').innerHTML=openFiles.map(n=>`<button class="open-tab ${n===selectedFile?'active':''}" data-file="${esc(n)}">${esc(n)}</button>`).join('');$('editingName').textContent=selectedFile||'لا يوجد ملف محدد';$('codeEditor').value=selectedFile?chat.files[selectedFile]:'';$('codeEditor').disabled=!selectedFile;$('statusFile').textContent=selectedFile||'No file';icons()}
  function setTab(tab){wsTab=tab;document.querySelectorAll('.ws-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(let name of ['files','preview','diff','versions','terminal','github','tools'])$(name+'Tab')?.classList.toggle('hidden',tab!==name);if(tab==='preview')renderPreview();if(tab==='diff')renderDiff();if(tab==='versions')renderVersions();if(tab==='github')renderGithub();if(tab==='tools')renderToolLog()}
  function htmlDocument(){let files=chat.files||{},html=files['index.html']||Object.entries(files).find(([n])=>n.endsWith('.html'))?.[1]||'<html><body><h2 style="font-family:sans-serif;text-align:center;margin:20vh auto;color:#8491a6">أنشئ ملف index.html لعرض المعاينة</h2></body></html>';let css=Object.entries(files).filter(([n])=>n.endsWith('.css')).map(([,v])=>v).join('\n'),js=Object.entries(files).filter(([n])=>n.endsWith('.js')).map(([,v])=>v).join('\n');html=html.replace(/<link\b[^>]*href=["'](?:\.\/)?([^"']+\.css)["'][^>]*>/gi,(full,name)=>files[name]?'':full).replace(/<script\b[^>]*src=["'](?:\.\/)?([^"']+\.js)["'][^>]*><\/script>/gi,(full,name)=>files[name]?'':full);let bytes=new TextEncoder().encode(js),binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));let encoded=btoa(binary);let bridge='<scr'+'ipt>window.addEventListener("error",e=>parent.postMessage({type:"aiway-preview-error",message:String(e.message||"Error"),source:String(e.filename||""),line:e.lineno||0},"*"));window.addEventListener("unhandledrejection",e=>parent.postMessage({type:"aiway-preview-error",message:String(e.reason?.message||e.reason||"Unhandled promise rejection")},"*"));</scr'+'ipt>';let injection=bridge+'<style>'+css+'</style>'+'<scr'+'ipt>eval(new TextDecoder().decode(Uint8Array.from(atob("'+encoded+'"),c=>c.charCodeAt(0))))</scr'+'ipt>';return html.includes('</body>')?html.replace('</body>',injection+'</body>'):html+injection}
