  function simpleDiff(oldText,newText){let a=String(oldText??'').split('\n'),b=String(newText??'').split('\n'),out=[],max=Math.max(a.length,b.length),shown=0;for(let i=0;i<max&&shown<180;i++){if(a[i]===b[i]){if(i<4||i>max-5){out.push(['same','  '+(a[i]??'')]);shown++}continue}if(a[i]!==undefined){out.push(['del','- '+a[i]]);shown++}if(b[i]!==undefined){out.push(['add','+ '+b[i]]);shown++}}if(max>180)out.push(['same','… diff مختصر …']);return out}
