  function renderDiff(){let box=$('diffList');if(!box)return;if(!pendingChanges){box.innerHTML='<div class="empty-mini">لا توجد تعديلات معلّقة.</div>';return}let names=changedNames();box.innerHTML=names.map(name=>{let before=pendingChanges.base?.[name],after=pendingChanges.files?.[name],kind=before===undefined?'ملف جديد':after===undefined?'حذف':'تعديل',lines=simpleDiff(before,after);return `<div class="diff-card"><div class="diff-head"><div><strong>${esc(name)}</strong> · ${kind}</div><div class="diff-buttons"><button class="primary-mini" data-diff-accept="${esc(name)}">قبول</button><button class="secondary-mini" data-diff-reject="${esc(name)}">رفض</button></div></div><div class="diff-code">${lines.map(([t,l])=>`<div class="diff-${t}">${esc(l)}</div>`).join('')}</div></div>`}).join('')||'<div class="empty-mini">لا توجد فروق.</div>';icons()}
  function acceptDiffFile(name){if(!pendingChanges)return;snapshotProject('قبل قبول تعديلات '+pendingChanges.source);if(Object.prototype.hasOwnProperty.call(pendingChanges.files,name)){chat.files[name]=pendingChanges.files[name];pendingChanges.base[name]=pendingChanges.files[name]}else{delete chat.files[name];delete pendingChanges.base[name]};if(!changedNames().length)pendingChanges=null;renderFiles();renderDiff();schedulePreview();saveChat()}
