  function appendTerminal(text,error=false){let line=String(text??'');terminalHistory.push(line);terminalHistory=terminalHistory.slice(-80);let el=document.createElement('div');el.className='term-line'+(error?' error':'');el.textContent=line;$('terminalOutput').appendChild(el);$('terminalOutput').scrollTop=$('terminalOutput').scrollHeight}
  function terminalRun(command){let raw=String(command||'').trim();if(!raw)return;appendTerminal('$ '+raw);let [cmd,...args]=raw.match(/(?:[^\s"]+|"[^"]*")+/g)||[];args=args.map(x=>x.replace(/^"|"$/g,''));try{if(cmd==='clear'){$('terminalOutput').innerHTML='';return}if(cmd==='help')return appendTerminal('Commands: help, clear, pwd, ls [path], cat <file>, head <file> [n], tail <file> [n], wc <file>, grep <text> <file>, git status, npm run');if(cmd==='pwd')return appendTerminal('/workspace');if(cmd==='ls'){let prefix=(args[0]||'').replace(/^\.\//,'').replace(/\/$/,'');let names=Object.keys(chat.files||{}).filter(n=>!prefix||n.startsWith(prefix));return appendTerminal(names.join('\n')||'(empty)')}if(['cat','head','tail','wc'].includes(cmd)){let path=safePath(args[0]);if(!(path in chat.files))throw Error('File not found: '+path);let txt=chat.files[path],lines=txt.split('\n'),n=Math.max(1,Math.min(200,Number(args[1]||10)));if(cmd==='cat')return appendTerminal(txt.slice(0,50000));if(cmd==='head')return appendTerminal(lines.slice(0,n).join('\n'));if(cmd==='tail')return appendTerminal(lines.slice(-n).join('\n'));return appendTerminal(`${lines.length} lines · ${txt.length} chars · ${new Blob([txt]).size} bytes`)}if(cmd==='grep'){let term=args[0],path=safePath(args[1]);if(!(path in chat.files))throw Error('File not found: '+path);let hits=chat.files[path].split('\n').map((l,i)=>[i+1,l]).filter(([,l])=>l.includes(term)).slice(0,100);return appendTerminal(hits.map(([i,l])=>`${i}: ${l}`).join('\n')||'No matches')}if(cmd==='git'&&args[0]==='status'){let pending=changedNames();return appendTerminal(`On virtual workspace\n${Object.keys(chat.files||{}).length} tracked workspace files\n${pending.length?pending.map(n=>'modified: '+n).join('\n'):'working tree clean'}`)}if(cmd==='npm'&&args[0]==='run'){let pkg=JSON.parse(chat.files['package.json']||'{}'),scripts=pkg.scripts||{};if(args[1])return appendTerminal(scripts[args[1]]?`Script ${args[1]}: ${scripts[args[1]]}\nExecution is delegated to Codex Agent mode for safety.`:`Unknown script: ${args[1]}`,!scripts[args[1]]);return appendTerminal(Object.entries(scripts).map(([k,v])=>`${k}: ${v}`).join('\n')||'No scripts in package.json')}throw Error('Command غير مدعوم في الـTerminal الآمن. اكتب help.')}catch(e){appendTerminal(e.message,true)}}
