  function chooseProviderFor(text){let p=provider();if(!autoMode)return p;let coding=/\b(code|bug|fix|build|refactor|implement|file|npm|test|html|css|javascript|typescript|python)\b|كود|برمج|ملف|ابن|اصلح|عدّل|تعديل|اختبار/i.test(text||'');let cp=providers.find(x=>x.type==='codex');if(coding&&codexReady&&codexAccountData?.type==='chatgpt'&&cp)return cp;return p}
