  function githubVisibleTree(){let q=($('githubTreeSearch')?.value||'').trim().toLowerCase();return (githubState.tree||[]).filter(x=>!q||x.path.toLowerCase().includes(q)).slice(0,1500)}
  function renderGithubTree(){let box=$('githubTreeList');if(!box)return;let rows=githubVisibleTree();box.innerHTML=(githubState.treeTruncated?'<div class="github-tree-warning">GitHub أعاد شجرة جزئية لأن المستودع ضخم. يمكنك تحديد الملفات الظاهرة، أو تضييق المشروع لاحقاً.</div>':'')+(rows.length?rows.map(x=>`<label class="github-tree-item"><input type="checkbox" data-github-path="${esc(x.path)}" ${githubState.selected.has(x.path)?'checked':''}><span>${esc(x.path)}</span><small>${formatBytes(x.size)}</small></label>`).join(''):'<div class="github-empty">لا توجد ملفات مطابقة.</div>');let selected=[...githubState.selected],bytes=(githubState.tree||[]).filter(x=>githubState.selected.has(x.path)).reduce((n,x)=>n+(x.size||0),0);$('githubSelectionSummary').textContent=selected.length?`${selected.length} ملف محدد · ${formatBytes(bytes)}`:'بدون تحديد: سيحاول AiWay تحميل المشروع النصي تلقائياً.'}
  async function githubBrowse(){let repo=$('githubRepo').value,branch=$('githubBranch').value;if(!repo||!branch){toast('اختر المستودع والفرع أولاً');return}try{$('githubStatus').textContent='Reading repository tree…';let data=await githubApi('tree',{query:{repo,branch}});githubState.tree=data.files||[];githubState.treeTruncated=!!data.truncated;let previous=new Set(chat?.github?.selectedPaths||[]);githubState.selected=new Set(githubState.tree.filter(x=>previous.has(x.path)).map(x=>x.path));$('githubTree').classList.remove('hidden');renderGithubTree();$('githubStatus').textContent=`${githubState.tree.length} ملف نصي متاح للاختيار${data.truncated?' · شجرة جزئية':''}`;}catch(e){$('githubStatus').textContent='Error: '+e.message;toast(e.message)}}
