  function renderGithub(){if(!$('githubStatus'))return;let connected=githubState.connected,user=githubState.user;$('githubSignedOut').classList.toggle('hidden',connected);$('githubSignedIn').classList.toggle('hidden',!connected);$('githubLogin').disabled=!githubState.configured||githubState.loading;$('githubConfigHint').textContent=githubState.configured?'بعد تسجيل الدخول ستظهر المستودعات التي لديك صلاحية للوصول إليها.':'GitHub OAuth غير مُعدّ على الخادم. أضف GITHUB_CLIENT_ID و GITHUB_CLIENT_SECRET.';if(user){$('githubUser').textContent='@'+user.login;$('githubAvatar').src=user.avatar||'';$('githubAvatar').alt=user.login}if(!connected){$('githubStatus').textContent=githubState.configured?'غير متصل':'GitHub OAuth غير مُعدّ';return}let current=chat?.github?.repo||'',repoSel=$('githubRepo');repoSel.innerHTML='<option value="">اختر مستودعاً…</option>'+githubState.repos.map(r=>`<option value="${esc(r.full_name)}">${esc(r.full_name)}${r.private?' · Private':''}</option>`).join('');repoSel.value=githubState.repos.some(r=>r.full_name===current)?current:'';renderGithubRepoMeta();let branch=chat?.github?.branch||'',branchSel=$('githubBranch');branchSel.innerHTML='<option value="">اختر فرعاً…</option>'+githubState.branches.map(b=>`<option value="${esc(b.name)}">${esc(b.name)}${b.protected?' · protected':''}</option>`).join('');branchSel.value=githubState.branches.some(b=>b.name===branch)?branch:'';$('githubStatus').textContent=githubState.loading?'Loading…':current?`Selected: ${current}${branch?' · '+branch:''}`:`متصل · ${githubState.repos.length} مستودع متاح`;icons()}
