  async function githubStatus(loadRepos=true){try{githubState.loading=true;let s=await githubApi('status');githubState.configured=!!s.configured;githubState.connected=!!s.connected;githubState.user=s.user||null;if(githubState.connected&&loadRepos)await githubRepos();else renderGithub()}catch(e){githubState.loading=false;githubState.connected=false;renderGithub();$('githubStatus').textContent='Error: '+e.message}}
  async function githubRepos(){try{githubState.loading=true;renderGithub();let data=await githubApi('repos');githubState.repos=data.repos||[];githubState.loading=false;let saved=chat?.github?.repo;if(saved&&githubState.repos.some(r=>r.full_name===saved)){await githubBranches(saved,false)}else{githubState.branches=[];renderGithub()}}catch(e){githubState.loading=false;renderGithub();$('githubStatus').textContent='Error: '+e.message;throw e}}
