  function commandItems(){let base=[['مشروع جديد','plus',()=>newChat()],['إعادة تسمية المشروع','pencil',renameProject],['نسخ المشروع','copy-plus',duplicateProject],['فتح الملفات','files',()=>{toggleWorkspace(true);setTab('files')}],['فتح المعاينة','monitor-play',()=>{toggleWorkspace(true);setTab('preview')}],['مراجعة Diff','git-compare-arrows',()=>{toggleWorkspace(true);setTab('diff')}],['سجل الإصدارات','history',()=>{toggleWorkspace(true);setTab('versions')}],['Terminal','terminal-square',()=>{toggleWorkspace(true);setTab('terminal')}],['GitHub','github',()=>{toggleWorkspace(true);setTab('github')}],['الإعدادات','settings-2',openSettings]];for(let name of Object.keys(chat?.files||{}))base.push(['فتح '+name,'file-code',()=>{selectedFile=name;toggleWorkspace(true);setTab('files');renderFiles()}]);return base}
