  function processToolCalls(message){let events=[];message.text=String(message.text||'').replace(/```aiway-tool\s*\n?([\s\S]*?)```/gi,(full,raw)=>{try{let call=JSON.parse(raw.trim());message.toolActivity={name:call.name||'tool',path:call.path||call.arguments?.path||''};let result=applyToolCall(call);events.push('✓ '+result)}catch(e){events.push('✕ '+e.message);logTool('tool_call','', 'error',e.message)}return ''}).trim();if(events.length){message.toolEvents=(message.toolEvents||[]).concat(events);setTimeout(()=>{if(message.toolActivity){message.toolActivity=null;if(chat?.messages?.includes(message))refreshLastMessage()}},650)}return events.length}
